use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,io::{Read,Write},path::{Path,PathBuf},process::{Command,Stdio}};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-cached-x175";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-29-g2-cached-x175";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn files(root:&Path)->Vec<PathBuf>{let mut v=vec![];for e in fs::read_dir(root).unwrap(){let p=e.unwrap().path();assert!(!p.is_symlink());if p.is_dir(){v.extend(files(&p))}else{v.push(p)}}v.sort();v}
fn archive(paths:&[PathBuf],base:&Path,out:&Path)->Value{let mut entries=BTreeMap::new();for p in paths{let bytes=fs::read(p).unwrap();let h=format!("{:x}",Sha256::digest(&bytes));let record=match String::from_utf8(bytes.clone()){Ok(s)=>json!({"sha256":h,"length":bytes.len(),"utf8":s}),Err(_)=>json!({"sha256":h,"length":bytes.len(),"hex":bytes.iter().map(|b|format!("{b:02x}")).collect::<String>()})};assert!(entries.insert(p.strip_prefix(base).unwrap().display().to_string(),record).is_none());}let bytes=serde_json::to_vec(&entries).unwrap();let temp=out.with_extension("json");fs::write(&temp,&bytes).unwrap();let f=fs::File::create(out).unwrap();assert!(Command::new("gzip").args(["-n","-c"]).arg(&temp).stdout(Stdio::from(f)).status().unwrap().success());let decoded=Command::new("gzip").arg("-dc").arg(out).output().unwrap();assert!(decoded.status.success());assert_eq!(decoded.stdout,bytes);let back:Value=serde_json::from_slice(&decoded.stdout).unwrap();for p in paths{let v=&back[p.strip_prefix(base).unwrap().to_str().unwrap()];let b=if let Some(s)=v["utf8"].as_str(){s.as_bytes().to_vec()}else{let s=v["hex"].as_str().unwrap();(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect()};assert_eq!(b,fs::read(p).unwrap());assert_eq!(v["sha256"],hash(p));}fs::remove_file(temp).unwrap();json!({"members":paths.len(),"sha256":hash(out),"roundtrip_exact":true})}


